141	     * Note, fetching `elsize` from the descriptor is OK even without the GIL,
142	     * however it may be that this should be moved into `auxdata` eventually,
143	     * which may also be slightly faster/cleaner (but more involved).
144	     */
145	    int len1 = context->descriptors[0]->elsize / sizeof(character);
146	    int len2 = context->descriptors[1]->elsize / sizeof(character);
147	
148	    char *in1 = data[0];
149	    char *in2 = data[1];
