160	                res = cmp == 0;
161	                break;
162	            case COMP::NE:
163	                res = cmp != 0;
164	                break;
165	            case COMP::LT:
166	                res = cmp < 0;
167	                break;
168	            case COMP::LE:
169	                res = cmp <= 0;
