134	template <bool rstrip, COMP comp, typename character>
135	static int
136	string_comparison_loop(PyArrayMethod_Context *context,
137	        char *const data[], npy_intp const dimensions[],
138	        npy_intp const strides[], NpyAuxData *NPY_UNUSED(auxdata))
139	{
140	    /*
141	     * Note, fetching `elsize` from the descriptor is OK even without the GIL,
142	     * however it may be that this should be moved into `auxdata` eventually,
143	     * which may also be slightly faster/cleaner (but more involved).
144	     */
145	    int len1 = context->descriptors[0]->elsize / sizeof(character);
146	    int len2 = context->descriptors[1]->elsize / sizeof(character);
147	
148	    char *in1 = data[0];
149	    char *in2 = data[1];
150	    char *out = data[2];
151	
152	    npy_intp N = dimensions[0];
153	
154	    while (N--) {
155	        int cmp = string_cmp<rstrip>(
156	                len1, (character *)in1, len2, (character *)in2);
157	        npy_bool res;
158	        switch (comp) {
159	            case COMP::EQ:
160	                res = cmp == 0;
161	                break;
162	            case COMP::NE:
163	                res = cmp != 0;
164	                break;
165	            case COMP::LT:
166	                res = cmp < 0;
167	                break;
168	            case COMP::LE:
169	                res = cmp <= 0;
170	                break;
171	            case COMP::GT:
172	                res = cmp > 0;
173	                break;
174	            case COMP::GE:
175	                res = cmp >= 0;
176	                break;
177	        }
178	        *(npy_bool *)out = res;
179	
180	        in1 += strides[0];
181	        in2 += strides[1];
182	        out += strides[2];
183	    }
184	    return 0;
185	}
