556	    }
557	    else if (PyDataType_FLAGCHK(descr, NPY_USE_GETITEM)) {
558	        return descr->f->getitem(data, base);
559	    }
560	    itemsize = descr->elsize;
561	    copyswap = descr->f->copyswap;
562	    type = descr->typeobj;
563	    swap = !PyArray_ISNBO(descr->byteorder);
564	    if (PyTypeNum_ISSTRING(type_num)) {
565	        /* Eliminate NULL bytes */
566	        char *dptr = data;
