576	             */
577	            itemsize = (((itemsize - 1) >> 2) + 1) << 2;
578	        }
579	    }
580	    if (type_num == NPY_UNICODE) {
581	        /* we need the full string length here, else copyswap will write too
582	           many bytes */
583	        void *buff = PyArray_malloc(descr->elsize);
584	        if (buff == NULL) {
585	            return PyErr_NoMemory();
586	        }
587	        /* copyswap needs an array object, but only actually cares about the
588	         * dtype
589	         */
590	        PyArrayObject_fields dummy_arr;
