/*
 * Fast-path predicate ids for common no-argument string predicate methods.
 * Used by _vec_string_predicate_fast below to avoid creating a Python
 * scalar/string object per array element.
 */
typedef enum {
    NPY_STR_PRED_NONE = -1,
    NPY_STR_PRED_ISALPHA = 0,
    NPY_STR_PRED_ISALNUM,
    NPY_STR_PRED_ISDIGIT,
    NPY_STR_PRED_ISSPACE,
    NPY_STR_PRED_ISNUMERIC,
    NPY_STR_PRED_ISDECIMAL
} npy_string_predicate_t;

static npy_string_predicate_t
_get_string_predicate(PyObject *method_name)
{
    if (method_name == NULL || !PyUnicode_Check(method_name)) {
        return NPY_STR_PRED_NONE;
    }
    Py_ssize_t name_len = 0;
    const char *name = PyUnicode_AsUTF8AndSize(method_name, &name_len);
    if (name == NULL) {
        PyErr_Clear();
        return NPY_STR_PRED_NONE;
    }
    if (name_len == 7 && name[0] == 'i' && name[1] == 's') {
        if (memcmp(name + 2, "alpha", 5) == 0) return NPY_STR_PRED_ISALPHA;
        if (memcmp(name + 2, "alnum", 5) == 0) return NPY_STR_PRED_ISALNUM;
        if (memcmp(name + 2, "digit", 5) == 0) return NPY_STR_PRED_ISDIGIT;
        if (memcmp(name + 2, "space", 5) == 0) return NPY_STR_PRED_ISSPACE;
    }
    else if (name_len == 9 && name[0] == 'i' && name[1] == 's') {
        if (memcmp(name + 2, "numeric", 7) == 0) return NPY_STR_PRED_ISNUMERIC;
        if (memcmp(name + 2, "decimal", 7) == 0) return NPY_STR_PRED_ISDECIMAL;
    }
    return NPY_STR_PRED_NONE;
}


/*
