    PyArrayObject *result = NULL;
    PyArrayIterObject *out_iter = NULL;
    int type_num = PyArray_TYPE(char_array);
    int elsize = PyArray_DESCR(char_array)->elsize;
    int char_size = (type_num == NPY_UNICODE) ? (int)sizeof(npy_ucs4) : 1;
    int char_count = (char_size > 0) ? (elsize / char_size) : 0;

