    if (in_iter == NULL) {
        Py_DECREF(type);
        goto fail;
    }

    result = (PyArrayObject *)PyArray_SimpleNewFromDescr(
            PyArray_NDIM(char_array), PyArray_DIMS(char_array), type);
    if (result == NULL) {
        goto fail;
    }

    out_iter = (PyArrayIterObject *)PyArray_IterNew((PyObject *)result);
    if (out_iter == NULL) {
        goto fail;
    }

    NPY_BEGIN_THREADS_DEF;
    NPY_BEGIN_THREADS_THRESHOLDED(PyArray_SIZE(char_array));

#define NPY_STR_PROCESS_UNICODE(PRED_FN) do {                              \
        while (PyArray_ITER_NOTDONE(in_iter)) {                            \
            const npy_ucs4 *str = (const npy_ucs4 *)in_iter->dataptr;      \
            int len = char_count;                                          \
            while (len > 0 && str[len - 1] == 0) {                         \
                len--;                                                     \
            }                                                              \
            npy_bool out_val = 0;                                          \
            if (len > 0) {                                                 \
                int i;                                                     \
                for (i = 0; i < len; i++) {                                \
                    if (!PRED_FN(str[i])) break;                           \
                }                                                          \
                if (i == len) out_val = 1;                                 \
            }                                                              \
            *(npy_bool *)out_iter->dataptr = out_val;                      \
            PyArray_ITER_NEXT(in_iter);                                    \
            PyArray_ITER_NEXT(out_iter);                                   \
        }                                                                  \
    } while (0)

#define NPY_STR_PROCESS_BYTES(PRED_FN) do {                                \
        while (PyArray_ITER_NOTDONE(in_iter)) {                            \
            const unsigned char *str = (const unsigned char *)             \
                    in_iter->dataptr;                                      \
            int len = char_count;                                          \
            while (len > 0 && str[len - 1] == 0) {                         \
                len--;                                                     \
            }                                                              \
            npy_bool out_val = 0;                                          \
            if (len > 0) {                                                 \
                int i;                                                     \
                for (i = 0; i < len; i++) {                                \
                    if (!PRED_FN(str[i])) break;                           \
                }                                                          \
                if (i == len) out_val = 1;                                 \
            }                                                              \
            *(npy_bool *)out_iter->dataptr = out_val;                      \
            PyArray_ITER_NEXT(in_iter);                                    \
            PyArray_ITER_NEXT(out_iter);                                   \
        }                                                                  \
    } while (0)

    if (type_num == NPY_UNICODE) {
        switch (pred) {
            case NPY_STR_PRED_ISALPHA:
                NPY_STR_PROCESS_UNICODE(Py_UNICODE_ISALPHA); break;
            case NPY_STR_PRED_ISALNUM:
                NPY_STR_PROCESS_UNICODE(Py_UNICODE_ISALNUM); break;
            case NPY_STR_PRED_ISDIGIT:
                NPY_STR_PROCESS_UNICODE(Py_UNICODE_ISDIGIT); break;
            case NPY_STR_PRED_ISSPACE:
                NPY_STR_PROCESS_UNICODE(Py_UNICODE_ISSPACE); break;
            case NPY_STR_PRED_ISNUMERIC:
                NPY_STR_PROCESS_UNICODE(Py_UNICODE_ISNUMERIC); break;
            case NPY_STR_PRED_ISDECIMAL:
                NPY_STR_PROCESS_UNICODE(Py_UNICODE_ISDECIMAL); break;
