         * and should have been filtered out by the caller. */
        switch (pred) {
            case NPY_STR_PRED_ISALPHA:
                NPY_STR_PROCESS_BYTES(Py_ISALPHA); break;
            case NPY_STR_PRED_ISALNUM:
                NPY_STR_PROCESS_BYTES(Py_ISALNUM); break;
            case NPY_STR_PRED_ISDIGIT:
                NPY_STR_PROCESS_BYTES(Py_ISDIGIT); break;
            case NPY_STR_PRED_ISSPACE:
                NPY_STR_PROCESS_BYTES(Py_ISSPACE); break;
            default:
                NPY_END_THREADS;
                goto fail;
        }
    }

#undef NPY_STR_PROCESS_UNICODE
#undef NPY_STR_PROCESS_BYTES

    NPY_END_THREADS;

    Py_DECREF(in_iter);
    Py_DECREF(out_iter);
    return (PyObject *)result;

